<?php include __DIR__.'/../partials/Header.php'; ?>
<h1>Staff Dashboard</h1><p>Welcome, <?= courtEscape($profile['name']) ?>. Manage reservations for your venue.</p>
<?php if (isset($_SESSION['staffMessage'])): $notice=$_SESSION['staffMessage']; unset($_SESSION['staffMessage']); ?><div class="alert alert-info" role="status"><?= courtEscape($notice['text']) ?></div><?php endif; ?>
<?php foreach (['Upcoming reservations'=>$upcomingBookings,'Recent reservations'=>$recentBookings] as $heading=>$rows): ?><section class="card mb-4"><h2 class="h4"><?= $heading ?></h2><?php if (!$rows): ?><p>No reservations to display.</p><?php else: ?><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Customer</th><th>Court</th><th>Date / time</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach ($rows as $booking): ?><tr><td><?= courtEscape($booking['userName']) ?></td><td><?= courtEscape($booking['courtName']) ?></td><td><?= courtEscape($booking['bookingDate'].' '.$booking['bookingTime']) ?></td><td><?= courtEscape($booking['status']) ?></td><td><?php if ($booking['status'] !== 'cancelled'): ?><form method="post" action="/index.php?url=dashboard/changeBookingStatus"><input type="hidden" name="bookingID" value="<?= (int)$booking['bookingID'] ?>"><select name="status" aria-label="Booking status"><?php foreach (['upcoming','completed','cancelled'] as $status): ?><option <?= $status===$booking['status']?'selected':'' ?>><?= $status ?></option><?php endforeach; ?></select><button class="btn btn-primary btn-sm mt-2">Save</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><?php endforeach; ?>
<?php include __DIR__.'/../partials/Footer.php'; ?>
